    "mMNVBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jYS",
                name = "mMNV",
                version = c(1,0,0),
                options = options,
                results = mMNVResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Repeated Measures & Profile Analysis
#'
#' Repeated Measures MANOVA without sphericity assumption (O'Brien & Kaiser, 
#' 1985) and Profile Analysis.
#' @param data .
#' @param rmCells .
#' @param rmFactorName .
#' @param between .
#' @param covs .
#' @param testPillai .
#' @param testWilks .
#' @param testHotelling .
#' @param testRoy .
#' @param contrastType .
#' @param showUnivariate .
#' @param showSphericity .
#' @param showProfileAnalysis .
#' @param showContrastsTable .
#' @param showAssumptionChecks .
#' @param showMeansTable .
#' @param showProfilePlot .
#' @param plotError .
#' @param showHePlot .
#' @param showOutlierPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multivariateTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$univariateTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sphericityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$profileTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$contrastsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$assumptionsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$meansTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$profilePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$hePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outlierPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$multivariateTable$asDF}
#'
#' \code{as.data.frame(results$multivariateTable)}
#'
#' @export
mMNV <- function(
    data,
    rmCells = list(),
    rmFactorName = "Time",
    between = list(),
    covs = list(),
    testPillai = TRUE,
    testWilks = TRUE,
    testHotelling = TRUE,
    testRoy = TRUE,
    contrastType = "polynomial",
    showUnivariate = TRUE,
    showSphericity = TRUE,
    showProfileAnalysis = TRUE,
    showContrastsTable = TRUE,
    showAssumptionChecks = TRUE,
    showMeansTable = TRUE,
    showProfilePlot = TRUE,
    plotError = "ci",
    showHePlot = FALSE,
    showOutlierPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mMNV requires jmvcore to be installed (restart may be required)")

    if ( ! missing(rmCells)) rmCells <- jmvcore::resolveQuo(jmvcore::enquo(rmCells))
    if ( ! missing(between)) between <- jmvcore::resolveQuo(jmvcore::enquo(between))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(rmCells), rmCells, NULL),
            `if`( ! missing(between), between, NULL),
            `if`( ! missing(covs), covs, NULL))

    for (v in between) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- mMNVOptions$new(
        rmCells = rmCells,
        rmFactorName = rmFactorName,
        between = between,
        covs = covs,
        testPillai = testPillai,
        testWilks = testWilks,
        testHotelling = testHotelling,
        testRoy = testRoy,
        contrastType = contrastType,
        showUnivariate = showUnivariate,
        showSphericity = showSphericity,
        showProfileAnalysis = showProfileAnalysis,
        showContrastsTable = showContrastsTable,
        showAssumptionChecks = showAssumptionChecks,
        showMeansTable = showMeansTable,
        showProfilePlot = showProfilePlot,
        plotError = plotError,
        showHePlot = showHePlot,
        showOutlierPlot = showOutlierPlot)

    analysis <- mMNVClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

